import random
PROMPT, OUT, SLO_TTFT, SLO_TPOT = 1024, 128, 0.400, 0.025

def cost(P, B):  # seconds for P prefill tokens + B decodes (lesson 1 toy)
    return max(15 + 0.2 * B, 0.1 * (P + B)) / 1000

def gpu(jobs, budget=None):
    """One GPU, continuous batching. jobs: [ready, prompt_left, decodes].
    Returns first-token and finish time per job index."""
    order = sorted(range(len(jobs)), key=lambda i: jobs[i][0])
    first, end, wait, run = {}, {}, [], {}
    clock, k = 0.0, 0
    while k < len(order) or wait or run:
        while k < len(order) and jobs[order[k]][0] <= clock:
            i = order[k]; k += 1
            if jobs[i][1]: wait.append(i)
            else: run[i] = jobs[i][2]          # KV arrived: decode only
        if not wait and not run:
            clock = jobs[order[k]][0]; continue
        room = budget - len(run) if budget else 10**9  # decodes first
        plan = []
        for i in wait:                         # FCFS prefill (chunks)
            n = min(jobs[i][1], room)
            if n <= 0: break
            plan.append((i, n)); room -= n
        clock += cost(sum(n for _, n in plan), len(run))
        for i in list(run):
            run[i] -= 1
            if run[i] == 0: end[i] = clock; del run[i]
        for i, n in plan:
            jobs[i][1] -= n
            if jobs[i][1] == 0:                # prompt done: token 1
                wait.remove(i); first[i] = clock
                if jobs[i][2]: run[i] = jobs[i][2]
    return first, end
